    """For each non-background color, extend a ray from its cell farthest from a reference point along the color's own line direction, stopping at edges or non-background cells."""
    bg = grid[0][0]; H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    byc = {}
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v != bg: byc.setdefault(v, []).append((i, j))
    singles = [ps[0] for ps in byc.values() if len(ps) == 1]
    if singles:
        ref = singles[0]
    elif ref is None:
        pts = [p for ps in byc.values() for p in ps]
        ref = (sum(p[0] for p in pts) / len(pts), sum(p[1] for p in pts) / len(pts))
    dirs = [(a, b) for a in (-1, 0, 1) for b in (-1, 0, 1) if (a, b) != (0, 0)]
    for v, ps in byc.items():
        if len(ps) < 2: continue
        p = max(ps, key=lambda q: (q[0] - ref[0]) ** 2 + (q[1] - ref[1]) ** 2)
